        // User2 registers a name - this should overwrite user1's registration due to uninitialized storage
        vm.prank(user2);
        registrar.register{value: 1 ether}(name2, mappedAddress2);

        // Check user2's registration
        assertEq(registrar.resolve(name2), mappedAddress2);

        // The vulnerability: check if user1's name record was corrupted
        // Since we can't directly access the struct, we'll check through the resolve mapping
        // If the storage was corrupted, user1's name might resolve incorrectly
        assertEq(registrar.resolve(name1), mappedAddress1, "User1's registration corrupted");

        // Alternatively, check if the names resolve correctly
        assertTrue(registrar.resolve(name1) != registrar.resolve(name2), "Names should resolve to different addresses");

